WITH base AS (SELECT * FROM suppliers WHERE rating >= 3.9), rating_bucket_summary AS (SELECT CASE WHEN rating >= 3.5 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END AS rating_bucket, ROUND(AVG(rating), 2) AS avg_rating FROM base GROUP BY CASE WHEN rating >= 3.5 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END) SELECT rating_bucket, avg_rating FROM rating_bucket_summary WHERE avg_rating > 75 ORDER BY 2 DESC;
